"use client";

import { useId, useState } from "react";

import { SparklesIcon } from "@/components/blocks/parts/icons";
import { CopyButton } from "@/components/motion/copy-button";
import { SegmentedControl } from "@/components/motion/segmented-control";
import { Button } from "@/components/ui/button";

import { BlockFrame } from "../parts/block-frame";
import { PlayIcon, StopIcon } from "./icons";
import { useElapsed, useInterval } from "./lib/timers";
import { GOAL, PLAN, SUMMARY } from "./agent-orchestrator/data";
import { LeadPanel } from "./agent-orchestrator/lead-panel";
import { advance, IDLE, startRun, stopRun, visibleSummary } from "./agent-orchestrator/run-state";
import { WorkerLane } from "./agent-orchestrator/worker-lane";

type Limit = "1" | "2" | "3" | "4";

const LIMITS: { value: Limit; label: string }[] = [
  { value: "1", label: "1" },
  { value: "2", label: "2" },
  { value: "3", label: "3" },
  { value: "4", label: "4" },
];

const TICK = 380;

/**
 * A lead agent splits a goal into a plan and hands each item to a worker,
 * running up to the chosen number at once. Each worker lane shows its live
 * action, tokens and cost and opens to its transcript. The lead merges what
 * comes back into one summary a person can copy.
 */
export function AgentOrchestrator({ className }: { className?: string }) {
  const titleId = useId();
  const [limit, setLimit] = useState<Limit>("2");
  const [state, setState] = useState(IDLE);
  const [runKey, setRunKey] = useState(0);
  const running = state.phase === "planning" || state.phase === "working" || state.phase === "summarizing";
  const seconds = useElapsed(running, runKey);

  useInterval(() => setState((current) => advance(current, Number(limit))), running ? TICK : null);

  const run = () => {
    setRunKey((key) => key + 1);
    setState(startRun());
  };

  const summary = visibleSummary(state);
  const showSummary = state.phase === "summarizing" || state.phase === "done";

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-center justify-between gap-x-6 gap-y-3 border-b border-border px-5 py-4">
        <div className="min-w-0">
          <h2 id={titleId} className="text-base font-semibold text-balance">
            {GOAL}
          </h2>
          <p className="text-sm text-muted-foreground">
            {PLAN.length} sub-tasks, up to {limit} {limit === "1" ? "worker" : "workers"} at once
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-3">
          <span className="flex items-center gap-2 text-sm text-muted-foreground">
            <span aria-hidden="true">Workers</span>
            <SegmentedControl aria-label="Workers at once" options={LIMITS} value={limit} onValueChange={setLimit} />
          </span>
          {running ? (
            <Button variant="outline" onClick={() => setState(stopRun)}>
              <StopIcon aria-hidden="true" />
              Stop
            </Button>
          ) : (
            <Button onClick={run}>
              <PlayIcon aria-hidden="true" />
              {state.phase === "idle" ? "Run" : "Run again"}
            </Button>
          )}
        </div>
      </header>

      <div className="flex flex-col gap-4 p-5">
        <LeadPanel state={state} seconds={seconds} />
        <ul aria-label="Workers" className="flex flex-col">
          {PLAN.map((task, index) => {
            const lane = state.lanes[task.id];
            if (!lane) return null;
            return (
              <WorkerLane
                key={task.id}
                task={task}
                lane={lane}
                packets={state.packets.filter((packet) => packet.lane === task.id)}
                last={index === PLAN.length - 1}
              />
            );
          })}
        </ul>
        {showSummary ? (
          <section aria-labelledby={`${titleId}-summary`} className="relative flex flex-col gap-2 rounded-xl p-4">
            <span aria-hidden="true" className="absolute inset-0 rounded-xl bg-muted/60" />
            <div className="relative flex items-center justify-between gap-3">
              <h3 id={`${titleId}-summary`} className="flex items-center gap-2 text-sm font-semibold">
                <SparklesIcon aria-hidden="true" className="size-4 text-chart-1" />
                Merged summary
              </h3>
              {state.phase === "done" ? <CopyButton value={SUMMARY} label="Copy summary" /> : null}
            </div>
            <p className="relative text-sm leading-relaxed">{summary}</p>
          </section>
        ) : null}
      </div>
      <p role="status" className="sr-only">
        {state.announcement}
      </p>
    </BlockFrame>
  );
}

