import { useEffect, useRef, useState } from "react";

/**
 * Calls `callback` every `delay` milliseconds while `delay` is a number, and
 * stops when it is null or the component unmounts. The latest callback always runs.
 */
export function useInterval(callback: () => void, delay: number | null) {
  const saved = useRef(callback);
  useEffect(() => {
    saved.current = callback;
  }, [callback]);
  useEffect(() => {
    if (delay === null) return;
    const id = window.setInterval(() => saved.current(), delay);
    return () => window.clearInterval(id);
  }, [delay]);
}

/**
 * Whole seconds since `running` last turned true. The count holds while
 * `running` is false and starts again from zero on `resetKey` change.
 */
export function useElapsed(running: boolean, resetKey: string | number = 0) {
  const [state, setState] = useState({ key: resetKey, seconds: 0 });
  // A new reset key starts the count again, adjusted during render rather than in an effect.
  if (state.key !== resetKey) setState({ key: resetKey, seconds: 0 });
  useInterval(() => setState((current) => ({ ...current, seconds: current.seconds + 1 })), running ? 1000 : null);
  return state.key === resetKey ? state.seconds : 0;
}

/**
 * Runs a list of timed steps one after another. Each step waits its `after`
 * milliseconds, then calls `run`. Every pending timer clears on unmount or when `key` changes.
 */
export function useSchedule(steps: { after: number; run: () => void }[] | null, key: string | number) {
  const saved = useRef(steps);
  useEffect(() => {
    saved.current = steps;
  });
  useEffect(() => {
    const list = saved.current;
    if (!list) return;
    const ids: number[] = [];
    let total = 0;
    for (const step of list) {
      total += step.after;
      ids.push(window.setTimeout(step.run, total));
    }
    return () => ids.forEach((id) => window.clearTimeout(id));
  }, [key]);
}

