/** Props for the lead agent's panel. */
export interface LeadPanelProps {
  state: RunState;
  seconds: number;
}

function leadLine(state: RunState) {
  const lanes = Object.values(state.lanes);
  const working = lanes.filter((lane) => lane.status === "working").length;
  const waiting = lanes.filter((lane) => lane.status === "waiting").length;
  if (state.phase === "idle") return "Ready to plan";
  if (state.phase === "planning") return "Writing the plan";
  if (state.phase === "working") return `${working} working, ${waiting} waiting`;
  if (state.phase === "summarizing") return "Merging the results";
  if (state.phase === "stopped") return "Stopped";
  return "Done";
}

/**
 * The lead agent: its model, what it is doing, elapsed time, tokens and cost,
 * then its plan. Plan items grow in one by one while their text streams in,
 * and each item takes the colour of the worker lane it becomes.
 */
export function LeadPanel({ state, seconds }: LeadPanelProps) {
  const reduceMotion = useReducedMotion();
  const busy = state.phase === "planning" || state.phase === "working" || state.phase === "summarizing";
  return (
    <section aria-label="Lead agent" className="flex flex-col gap-3">
      <div className="flex flex-wrap items-center gap-x-4 gap-y-1">
        <span className="flex items-center gap-2">
          <span aria-hidden="true" className="flex size-7 items-center justify-center rounded-lg bg-foreground text-background">
            <SparklesIcon className="size-4" />
          </span>
          <h3 className="text-sm font-semibold">Lead agent</h3>
          <span className="rounded-full border border-border px-2 py-0.5 text-xs text-muted-foreground">{LEAD_MODEL}</span>
        </span>
        <span className="flex items-center gap-1.5 text-sm text-muted-foreground">
          {busy ? <LoaderIcon aria-hidden="true" className="size-3.5 motion-safe:animate-spin" /> : null}
          {leadLine(state)}
        </span>
        <span className="ml-auto flex gap-3 text-xs text-muted-foreground tabular-nums">
          <span>{formatSeconds(seconds)}</span>
          <span>
            <NumberTicker value={state.leadTokens} format={ROLL_WHOLE} /> tokens
          </span>
          <span>{formatCost((state.leadTokens / 1000) * LEAD_RATE)}</span>
        </span>
      </div>
      {state.phase === "idle" ? (
        <p className="text-sm text-muted-foreground">Run the goal and the lead writes a plan, then hands each item to a worker.</p>
      ) : (
        <ol aria-label="Plan" className="flex flex-col gap-1">
          {PLAN.map((task, index) => {
            const shown = visibleChars(state.planChars, index);
            if (shown === 0) return null;
            const lane = state.lanes[task.id];
            return (
              <motion.li
                key={task.id}
                initial={reduceMotion ? false : { opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: "auto" }}
                transition={reduceMotion ? { duration: 0 } : { type: "spring", stiffness: 380, damping: 39 }}
                className="flex items-center gap-2.5 overflow-hidden text-sm"
              >
                <span aria-hidden="true" className="w-4 shrink-0 text-right text-xs text-muted-foreground tabular-nums">
                  {index + 1}
                </span>
                <span aria-hidden="true" className={cn("size-2 shrink-0 rounded-full", task.hue.fill)} />
                <span className="min-w-0 flex-1 truncate">{task.title.slice(0, shown)}</span>
                {lane?.status === "done" ? <CheckIcon aria-label="Done" className={cn("size-4 shrink-0", task.hue.text)} /> : null}
              </motion.li>
            );
          })}
        </ol>
      )}
    </section>
  );
}

const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const COMPACT = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const CENTS = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", minimumFractionDigits: 2, maximumFractionDigits: 2 });

/** Seconds as a short clock reading, such as "48s" or "2m 05s". */
export function formatSeconds(seconds: number) {
  const whole = Math.max(0, Math.round(seconds));
  if (whole < 60) return `${whole}s`;
  const minutes = Math.floor(whole / 60);
  const rest = whole % 60;
  if (minutes < 60) return `${minutes}m ${String(rest).padStart(2, "0")}s`;
  return `${Math.floor(minutes / 60)}h ${String(minutes % 60).padStart(2, "0")}m`;
}

/** A token count, such as "840" or "12.4K". */
export const formatTokens = (value: number) => (value < 1000 ? WHOLE.format(Math.round(value)) : COMPACT.format(value));

/** A cost with cents, such as "$0.42". */
export const formatCost = (value: number) => CENTS.format(value);

/** A whole number with separators. */
export const formatCount = (value: number) => WHOLE.format(Math.round(value));

/** Roll formats for `NumberTicker`. Module constants, because the ticker memoises its formatter on them. */
export const ROLL_WHOLE: Intl.NumberFormatOptions = { maximumFractionDigits: 0 };
/** One decimal place, for a score or a percent. */
export const ROLL_ONE_PLACE: Intl.NumberFormatOptions = { minimumFractionDigits: 1, maximumFractionDigits: 1 };
/** Dollars with cents. */
export const ROLL_CENTS: Intl.NumberFormatOptions = { style: "currency", currency: "USD", minimumFractionDigits: 2, maximumFractionDigits: 2 };

import { PLAN, SUMMARY } from "./data";

/** Where the whole run stands. */
export type Phase = "idle" | "planning" | "working" | "summarizing" | "done" | "stopped";

/** Where one worker lane stands. */
export type LaneStatus = "waiting" | "working" | "done" | "stopped";

/** One worker lane during a run. */
export interface Lane {
  status: LaneStatus;
  /** The step in progress, or the step count once the lane is done. */
  step: number;
  ticksInStep: number;
  tokens: number;
}

/** A short coloured mark that travels along a connector: out to a worker, or back to the lead. */
export interface Packet {
  id: number;
  lane: string;
  direction: "out" | "back";
  born: number;
}

/** The whole run, advanced one tick at a time. */
export interface RunState {
  phase: Phase;
  tick: number;
  /** Characters of the plan shown so far, counted across every item in order. */
  planChars: number;
  lanes: { [laneId: string]: Lane };
  packets: Packet[];
  summaryChars: number;
  leadTokens: number;
  /** The last thing worth saying aloud. */
  announcement: string;
}

const PLAN_LENGTH = PLAN.reduce((sum, task) => sum + task.title.length, 0);

const freshLanes = () => Object.fromEntries(PLAN.map((task) => [task.id, { status: "waiting" as const, step: 0, ticksInStep: 0, tokens: 0 }]));

/** The state before any run, or after a reset. */
export const IDLE: RunState = {
  phase: "idle",
  tick: 0,
  planChars: 0,
  lanes: freshLanes(),
  packets: [],
  summaryChars: 0,
  leadTokens: 0,
  announcement: "",
};

/** A new run, starting with the lead writing its plan. */
export const startRun = (): RunState => ({ ...IDLE, lanes: freshLanes(), phase: "planning", announcement: "The lead agent is writing its plan." });

/** Stops the run where it is. Working lanes stop; finished lanes keep their result. */
export function stopRun(state: RunState): RunState {
  const lanes = Object.fromEntries(
    Object.entries(state.lanes).map(([id, lane]) => [id, lane.status === "working" ? { ...lane, status: "stopped" as const } : lane]),
  );
  return { ...state, phase: "stopped", lanes, packets: [], announcement: "Run stopped." };
}

/** How many characters of plan item `index` are showing. */
export function visibleChars(planChars: number, index: number) {
  const before = PLAN.slice(0, index).reduce((sum, task) => sum + task.title.length, 0);
  return Math.max(0, Math.min(PLAN[index]?.title.length ?? 0, planChars - before));
}

/** The visible part of the merged summary. */
export const visibleSummary = (state: RunState) => SUMMARY.slice(0, state.summaryChars);

/** Advances the run by one tick. `limit` is how many workers may run at once. */
export function advance(state: RunState, limit: number): RunState {
  const tick = state.tick + 1;
  const packets = state.packets.filter((packet) => packet.born > tick - 3);

  if (state.phase === "planning") {
    const planChars = state.planChars + 14;
    const done = planChars >= PLAN_LENGTH;
    return {
      ...state,
      tick,
      packets,
      planChars,
      leadTokens: state.leadTokens + 80,
      phase: done ? "working" : "planning",
      announcement: done ? `Plan ready with ${PLAN.length} sub-tasks.` : state.announcement,
    };
  }

  if (state.phase === "working") {
    const lanes = { ...state.lanes };
    let announcement = state.announcement;
    for (const task of PLAN) {
      const lane = lanes[task.id];
      if (!lane || lane.status !== "working") continue;
      const next = { ...lane, ticksInStep: lane.ticksInStep + 1, tokens: lane.tokens + task.tokensPerTick };
      if (next.ticksInStep >= task.ticksPerStep) {
        next.step += 1;
        next.ticksInStep = 0;
      }
      if (next.step >= task.steps.length) {
        next.status = "done";
        packets.push({ id: tick * 10 + PLAN.indexOf(task), lane: task.id, direction: "back", born: tick });
        announcement = `Worker finished: ${task.title}. ${task.result}`;
      }
      lanes[task.id] = next;
    }
    let working = Object.values(lanes).filter((lane) => lane.status === "working").length;
    for (const task of PLAN) {
      const lane = lanes[task.id];
      if (working >= limit) break;
      if (!lane || lane.status !== "waiting") continue;
      lanes[task.id] = { ...lane, status: "working" };
      packets.push({ id: tick * 10 + 5 + PLAN.indexOf(task), lane: task.id, direction: "out", born: tick });
      working += 1;
    }
    const allDone = Object.values(lanes).every((lane) => lane.status === "done");
    return {
      ...state,
      tick,
      packets,
      lanes,
      leadTokens: state.leadTokens + 25,
      phase: allDone ? "summarizing" : "working",
      announcement: allDone ? "Every worker is done. The lead is merging the results." : announcement,
    };
  }

  if (state.phase === "summarizing") {
    const summaryChars = Math.min(SUMMARY.length, state.summaryChars + 14);
    const done = summaryChars >= SUMMARY.length;
    return {
      ...state,
      tick,
      packets,
      summaryChars,
      leadTokens: state.leadTokens + 60,
      phase: done ? "done" : "summarizing",
      announcement: done ? "Summary ready." : state.announcement,
    };
  }

  return state;
}

