/** Props for one worker lane. */
export interface WorkerLaneProps {
  task: SubTask;
  lane: Lane;
  /** Packets now travelling along this lane's connector. */
  packets: Packet[];
  /** The last lane ends the trunk line at its connector. */
  last: boolean;
}

const STATUS_WORD = { waiting: "Waiting", working: "Working", done: "Done", stopped: "Stopped" } satisfies Record<Lane["status"], string>;

/**
 * One worker: a coloured connector from the lead's trunk, then a card with
 * the sub-task, the model, the live action, tokens and cost. The card opens
 * to show the worker's transcript. A packet runs out along the connector when
 * the lead dispatches the task, and back when the worker returns its result.
 */
export function WorkerLane({ task, lane, packets, last }: WorkerLaneProps) {
  const [open, setOpen] = useState(false);
  const panelId = useId();
  const reduceMotion = useReducedMotion();
  const active = lane.status !== "waiting";
  const current = task.steps[Math.min(lane.step, task.steps.length - 1)];
  const line =
    lane.status === "done" ? task.result : lane.status === "working" ? (current?.action ?? "") : lane.status === "stopped" ? "Stopped before it finished" : "Waiting for a free worker";
  const finished = task.steps.slice(0, lane.step);

  return (
    <li className="grid grid-cols-[2rem_minmax(0,1fr)] @md:grid-cols-[3rem_minmax(0,1fr)]">
      <div aria-hidden="true" className="relative">
        <span className={cn("absolute left-3 top-0 w-px bg-border", last ? "h-8" : "h-full")} />
        <span
          className={cn(
            "absolute top-8 right-0 left-3 h-0.5 -translate-y-1/2 rounded-full motion-safe:transition-colors",
            active ? task.hue.fill : "bg-border",
          )}
        />
        {reduceMotion ? null : (
          <AnimatePresence>
            {packets.map((packet) => (
              <motion.span
                key={packet.id}
                initial={{ left: packet.direction === "out" ? "0.75rem" : "100%", opacity: 0 }}
                animate={{ left: packet.direction === "out" ? "100%" : "0.75rem", opacity: [0, 1, 1, 0] }}
                exit={{ opacity: 0 }}
                transition={{ duration: 0.6, ease: "easeInOut" }}
                className={cn("absolute top-8 size-2 -translate-x-1/2 -translate-y-1/2 rounded-full ring-2 ring-card", task.hue.fill)}
              />
            ))}
          </AnimatePresence>
        )}
      </div>
      <div className="relative min-w-0 py-1.5">
        <span aria-hidden="true" className="absolute inset-x-0 inset-y-1.5 rounded-xl border border-border" />
        <Button
          variant="ghost"
          aria-expanded={open}
          aria-controls={panelId}
          onClick={() => setOpen(!open)}
          size="sm"
          className="relative w-full justify-start"
        >
<span className="flex min-h-13 w-full items-center gap-3 px-3 py-2.5 text-left font-normal whitespace-normal">
          <AppMark app={task.app} size="md" className={cn(task.hue.fill, !active && "opacity-40")} />
          <span className="flex min-w-0 flex-1 flex-col gap-0.5">
            <span className="flex min-w-0 items-center gap-2">
              <span className="line-clamp-2 text-sm font-medium">{task.title}</span>
              <span className="sr-only">, {STATUS_WORD[lane.status]}</span>
            </span>
            <span className={cn("truncate text-xs", lane.status === "done" ? "text-foreground" : "text-muted-foreground")}>
              <ShimmerText text={line} active={lane.status === "working"} />
            </span>
          </span>
          <span className="hidden shrink-0 flex-col items-end text-xs text-muted-foreground tabular-nums @md:flex">
            <span>{WORKER_MODEL}</span>
            <span>
              <NumberTicker value={lane.tokens} format={ROLL_WHOLE} /> tokens, {formatCost((lane.tokens / 1000) * WORKER_RATE)}
            </span>
          </span>
          {lane.status === "done" ? (
            <CheckIcon aria-hidden="true" className={cn("size-4 shrink-0", task.hue.text)} />
          ) : lane.status === "working" ? (
            <LoaderIcon aria-hidden="true" className={cn("size-4 shrink-0 motion-safe:animate-spin", task.hue.text)} />
          ) : null}
          <ChevronDownIcon aria-hidden="true" className={cn("size-4 shrink-0 text-muted-foreground motion-safe:transition-transform", open && "rotate-180")} />
        </span>
</Button>
        <Reveal open={open} id={panelId}>
          <div className="relative flex flex-col gap-2 px-4 pb-3 text-xs">
            <p className="text-muted-foreground tabular-nums @md:hidden">
              {WORKER_MODEL}, {lane.tokens.toLocaleString("en-US")} tokens, {formatCost((lane.tokens / 1000) * WORKER_RATE)}
            </p>
            {finished.length === 0 && lane.status !== "working" ? (
              <p className="text-muted-foreground">Nothing yet. The transcript fills in as the worker runs.</p>
            ) : (
              <ol aria-label={`${task.title} transcript`} className="flex flex-col gap-2">
                {finished.map((step) => (
                  <li key={step.action} className="flex flex-col gap-0.5 border-l-2 border-border pl-3">
                    <span className="font-medium">{step.action}</span>
                    <span className="text-muted-foreground">{step.output}</span>
                  </li>
                ))}
                {lane.status === "working" && current ? (
                  <li className={cn("border-l-2 pl-3 font-medium", task.hue.border)}>
                    <ShimmerText text={`${current.action}...`} active />
                  </li>
                ) : null}
              </ol>
            )}
          </div>
        </Reveal>
      </div>
    </li>
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import type { ReactNode } from "react";

import { cn } from "@/lib/utils";

/** Props for a region that opens to its full height. */
export interface RevealProps {
  open: boolean;
  children: ReactNode;
  /** An id, so the control that opens it can point at it with `aria-controls`. */
  id?: string;
  className?: string;
}

// Critically damped: 2 * sqrt(380) is about 39, so the height lands without a wobble.
const HEIGHT: Transition = { type: "spring", stiffness: 380, damping: 39, mass: 1 };

/**
 * Opens from zero to its full height on a critically damped spring. The
 * content fades in a beat after the height starts and fades out a beat before
 * it ends, and rises a little into place. With reduced motion it appears at once.
 */
export function Reveal({ open, children, id, className }: RevealProps) {
  const reduceMotion = useReducedMotion();
  return (
    <AnimatePresence initial={false}>
      {open ? (
        <motion.div
          key="reveal"
          id={id}
          initial={reduceMotion ? false : { height: 0 }}
          animate={{ height: "auto", transition: reduceMotion ? { duration: 0 } : HEIGHT }}
          exit={reduceMotion ? { height: 0, transition: { duration: 0 } } : { height: 0, transition: { ...HEIGHT, delay: 0.05 } }}
          className="overflow-hidden"
        >
          <motion.div
            initial={reduceMotion ? false : { opacity: 0, y: 4 }}
            animate={{ opacity: 1, y: 0, transition: { duration: 0.18, delay: reduceMotion ? 0 : 0.06 } }}
            exit={{ opacity: 0, y: reduceMotion ? 0 : 4, transition: { duration: reduceMotion ? 0 : 0.12 } }}
            className={cn(className)}
          >
            {children}
          </motion.div>
        </motion.div>
      ) : null}
    </AnimatePresence>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";

import { cn } from "@/lib/utils";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

/** Props for a line of text that shimmers while its work runs. */
export interface ShimmerTextProps {
  text: string;
  /** The text shimmers only while this is true. */
  active: boolean;
  className?: string;
}

/**
 * A short line, such as the verb of a running step, with a light band that
 * sweeps across it while `active` is true. With reduced motion the text stays still.
 */
export function ShimmerText({ text, active, className }: ShimmerTextProps) {
  const reduceMotion = useReducedMotion();
  if (!active || reduceMotion) return <span className={className}>{text}</span>;
  return (
    <motion.span
      className={cn(
        "bg-linear-to-r from-muted-foreground via-foreground to-muted-foreground bg-size-(--shimmer) bg-clip-text text-transparent",
        className,
      )}
      style={
        // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
        { "--shimmer": "200% 100%" } as VarStyle
      }
      initial={{ backgroundPosition: "100% 0" }}
      animate={{ backgroundPosition: "-100% 0" }}
      transition={{ duration: 1.6, ease: "linear", repeat: Infinity }}
    >
      {text}
    </motion.span>
  );
}

import type { CSSProperties } from "react";

/**
 * An inline style made only of custom properties, for values known at render
 * such as a point's place in a plot. Classes read them, as `left-(--x)` does.
 */
export type VarStyle = CSSProperties & { [name: `--${string}`]: string | number };
